// O no de busca devolve um item vazio (sem .id) quando nao acha nada, ou um
// item de erro se a busca falhou -- os dois casos contam como 'sem duplicado',
// para nao travar uma edicao por causa de um problema na checagem em si.
const achados = $input.all().filter((item) => item.json && item.json.id && !item.json.error);
const encontrado = achados[0];
return [{
  json: {
    duplicado: Boolean(encontrado),
    nomeDuplicado: encontrado ? (encontrado.json.fields?.Razao_Social_Nome || '') : '',
  },
}];

const achado = $input.all().map((i) => i.json).find((j) => j && j.id && !j.error);
if (!achado) return [{ json: { semEntidade: true } }];
const f = achado.fields || {};
return [{ json: {
  entidadeId: achado.id,
  asaasCustomerId: f.Asaas_Customer_Id || "",
  razaoSocial: f.Razao_Social_Nome || "",
  documento: f.CPF_CNPJ || "",
  emailNfe: f.Emails_Financeiro_NFE || "",
  localId: (f.Locais_Atendimento || [])[0] || "",
  contatoId: (f.Contatos_Solicitantes || [])[0] || "",
} }];

const texto = (v) => String(v ?? "").trim();
const soDigitos = (v) => texto(v).replace(/[^0-9]/g, "");

// Endereco guardado como um texto so: "RUA X, 100, CEP 00000-000", as vezes
// com complemento no meio. Enquanto seguir esse padrao (e ele sempre seguiu
// ate hoje, vindo da consulta a Receita), da para separar de volta. Se um dia
// alguem digitar diferente, o CEP/numero saem vazios -- nao trava, so manda
// incompleto para a Asaas.
function separaEndereco(enderecoCompleto) {
  const bruto = texto(enderecoCompleto);
  const mCep = bruto.match(/CEP\s*([0-9]{5}-?[0-9]{3})/i);
  const postalCode = mCep ? mCep[1].replace("-", "") : "";
  const semCep = bruto.replace(/,?\s*CEP\s*[0-9-]+/i, "").trim();
  const partes = semCep.split(",").map((p) => p.trim()).filter(Boolean);
  return {
    address: partes[0] || "",
    addressNumber: partes[1] || "",
    complement: partes.slice(2).join(", ") || "",
    postalCode,
  };
}

function separaBairro(bairroCidade) {
  return texto(String(bairroCidade || "").split("/")[0]);
}

// Numero brasileiro sem o 55 na frente: e o formato que a Asaas espera em
// mobilePhone. Sobra o DDD + numero.
function celularAsaas(v) {
  let d = soDigitos(v);
  if (d.length > 11 && d.startsWith("55")) d = d.slice(2);
  return d;
}

// Monta o corpo da Asaas so com o que realmente tem valor: mandar chave com
// string vazia e diferente de nao mandar a chave (a Asaas trataria como
// "apagar o que tinha").
function montaPayload({ razaoSocial, documento, emailNfe, emailsContato, whatsappContato, enderecoCompleto, bairroCidade }) {
  const end = separaEndereco(enderecoCompleto);
  const provincia = separaBairro(bairroCidade);
  const celular = celularAsaas(whatsappContato);

  // TODOS os e-mails (Financeiro/NF-e + todos os do contato), sem repetir.
  // O primeiro vira o principal; o resto vai em additionalEmails, separados
  // por virgula -- e assim que a Asaas aceita mais de um endereco extra.
  const brutos = [texto(emailNfe)].concat(Array.isArray(emailsContato) ? emailsContato.map(texto) : []);
  const semRepetir = [];
  brutos.filter(Boolean).forEach((e) => {
    if (!semRepetir.some((x) => x.toLowerCase() === e.toLowerCase())) semRepetir.push(e);
  });
  const principal = semRepetir[0] || "";
  const adicionais = semRepetir.slice(1).join(",");

  const p = { name: texto(razaoSocial), cpfCnpj: soDigitos(documento) };
  if (principal) p.email = principal;
  if (adicionais) p.additionalEmails = adicionais;
  if (celular) p.mobilePhone = celular;
  if (end.address) p.address = end.address;
  if (end.addressNumber) p.addressNumber = end.addressNumber;
  if (end.complement) p.complement = end.complement;
  if (end.postalCode) p.postalCode = end.postalCode;
  if (provincia) p.province = provincia;
  return p;
}

const base = $("Monta ids do local e contato").first().json;
if (base.semEntidade) return [{ json: { pular: true } }];

const local = $("Busca local atual").all().map((i) => i.json).find((j) => j && j.id && !j.error) || {};
const lf = local.fields || {};

const contato = $input.all().map((i) => i.json).find((j) => j && j.id && !j.error) || {};
const cf = contato.fields || {};
const emailsBrutos = Array.isArray(cf.Emails) ? cf.Emails : String(cf.Emails || "").split("\n");
const whatsapps = Array.isArray(cf.WhatsApps) ? cf.WhatsApps : String(cf.WhatsApps || "").split("\n");
const emailsContato = emailsBrutos.map((s) => s.trim()).filter(Boolean);
const whatsappContato = (whatsapps.map((s) => s.trim()).filter(Boolean))[0] || "";

const payload = montaPayload({
  razaoSocial: base.razaoSocial, documento: base.documento, emailNfe: base.emailNfe,
  emailsContato, whatsappContato,
  enderecoCompleto: lf.Endereco_Completo, bairroCidade: lf.Bairro_Cidade,
});
payload.externalReference = base.entidadeId;

const temAsaas = Boolean(base.asaasCustomerId);
// So manda notificationDisabled quando esta CRIANDO. Numa edicao normal
// essa chave nunca e mandada, entao uma mudanca manual na Asaas nao volta
// atras sozinha.
if (!temAsaas) payload.notificationDisabled = true;

return [{ json: {
  payload, entidadeId: base.entidadeId, asaasCustomerIdAtual: base.asaasCustomerId,
  metodo: temAsaas ? "PUT" : "POST",
  url: temAsaas ? ("https://api.asaas.com/v3/customers/" + base.asaasCustomerId) : "https://api.asaas.com/v3/customers",
} }];

const DESEJADO = [{"event":"PAYMENT_CREATED","offset":0,"email":true,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_UPDATED","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_DUEDATE_WARNING","offset":10,"email":true,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_DUEDATE_WARNING","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"SEND_LINHA_DIGITAVEL","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_OVERDUE","offset":0,"email":true,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_OVERDUE","offset":7,"email":true,"sms":false,"whatsapp":false,"ligacao":false},{"event":"PAYMENT_RECEIVED","offset":0,"email":false,"sms":false,"whatsapp":false,"ligacao":false}];
const lista = ($input.first().json || {}).data || [];

const itens = [];
for (const alvo of DESEJADO) {
  const atual = lista.find((n) => n.event === alvo.event && n.scheduleOffset === alvo.offset);
  if (!atual) continue;
  itens.push({ json: {
    url: "https://api.asaas.com/v3/notifications/" + atual.id,
    corpo: {
      emailEnabledForCustomer: alvo.email, smsEnabledForCustomer: alvo.sms,
      whatsappEnabledForCustomer: alvo.whatsapp, phoneCallEnabledForCustomer: alvo.ligacao,
    },
  } });
}
// Se a Asaas mudar os nomes dos eventos algum dia e nada bater, ainda
// precisa sair um item, senao o fluxo morre aqui e o app fica esperando.
if (!itens.length) return [{ json: { semNotificacao: true } }];
return itens;
